<script module lang="ts">
/**
 * A column of items of one kind, each read, followed or picked (`design/components/list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  agentMember,
  chooseListItem,
  currentListItem,
  joinSlot,
  listItems,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListProps {
  /**
   * `List.Item`s.
   */
  children?: Snippet
  /**
   * Names the list for a reader: "Notifications", not "List".
   */
  label: string
}
</script>

<script lang="ts">
let { children, label: labelOwn }: ListProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let list = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'List',
    element: () => list,
    state: () => ({
      items: listItems(list, styles.primary),
      current: currentListItem(list, styles.primary),
    }),
    actions: {
      choose: { argument: 'id', run: (value) => chooseListItem(list, styles.primary, value) },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<ul bind:this={list} class={styles.list} role="list" aria-label={label} data-member="list"
    >{@render children?.()
  }</ul
>{/if
}{@render joined.end?.()}
